module cookie_distribution (\n    input clk,\n    input rst_n,\n    input start,\n    input [31:0] N,\n    input [31:0] A,\n    input [31:0] B,\n    input [31:0] C,\n    output reg [63:0] result,\n    output reg done\n);\n    // State encoding\n    localparam IDLE = 1'b0;\n    localparam COMPUTE = 1'b1;\n    \n    reg state;\n    \n    // Combinational logic for computation\n    wire [63:0] A_ext = {32'd0, A};\n    wire [63:0] B_ext = {32'd0, B};\n    wire [63:0] C_ext = {32'd0, C};\n    wire [63:0] N_ext = {32'd0, N};\n    \n    wire [63:0] T = A_ext + B_ext + C_ext;\n    wire [63:0] M = max3(A_ext, B_ext, C_ext);\n    wire [63:0] two_M = M << 1;\n    wire [63:0] T_plus_N = T + N_ext;\n    wire condition = (two_M <= T_plus_N);\n    wire [63:0] part = T - M;\n    wire [63:0] two_part = part << 1;\n    wire [63:0] else_result = two_part + N_ext;\n    wire [63:0] computed_result = condition ? T : else_result;\n    \n    // Max function\n    function automatic [63:0] max3;\n        input [63:0] a, b, c;\n        begin\n            max3 = (a > b) ? ((a > c) ? a : c) : ((b > c) ? b : c);\n        end\n    endfunction\n    \n    // Sequential logic\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            result <= 64'd0;\n            done <= 1'b0;\n            state <= IDLE;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE;\n                    end\n                end\n                COMPUTE: begin\n                    result <= computed_result;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule